(function(root){
const questions=[['ROOM_001','ไฟแสงสว่างภายในห้องเครื่องเพียงพอ','ห้องเครื่อง'],['ROOM_002','ไฟฉุกเฉินพร้อมใช้งาน','ห้องเครื่อง'],['ROOM_003','การระบายอากาศภายในห้องเครื่อง','ห้องเครื่อง'],['CTRL_001','ความสะอาดภายในตู้ควบคุม','ตู้ควบคุม'],['PUMP_001','สภาพภายนอกและความสะอาดของ Fire Pump','เครื่องสูบน้ำ'],['PUMP_005','ระบบน้ำยาหล่อเย็นและท่อน้ำ','เครื่องสูบน้ำ'],['PUMP_006','ระดับน้ำมันเครื่องและรอยรั่วซึม','เครื่องสูบน้ำ']];
const seed=()=>({version:1,active:'pm151',projects:[{id:'pm151',code:'PM.FP.69-151',customer:'บริษัท ครัวการบินกรุงเทพ เชียงใหม่ จำกัด',site:'สำนักงานใหญ่',date:'2026-10-21',template:'PM-FP-001',status:'DRAFT',engine:'CLARKE JU4HNL24 / PENTAIR 5X6X110',serial:'',ratedFlow:750,ratedPressure:null,answers:{},tests:[{point:0,flow:null,discharge:null,suction:null,status:'PENDING'},{point:100,flow:null,discharge:null,suction:null,status:'PENDING'},{point:150,flow:null,discharge:null,suction:null,status:'PENDING'}],summary:'',notes:'',cover:null,sections:['cover','inspection','performance','findings','appendix'],revision:1,snapshots:[],history:[]},{id:'agc95',code:'PM.FP.69-095',customer:'บริษัท เอจีซี ไมโคร กลาส (ประเทศไทย) จำกัด',site:'โรง C',date:'2026-07-10',template:'PT-FP-001',status:'DRAFT',engine:'Fire Pump System',serial:'',ratedFlow:750,ratedPressure:null,answers:{},tests:[{point:0,flow:null,discharge:null,suction:null,status:'PENDING'},{point:100,flow:null,discharge:null,suction:null,status:'PENDING'},{point:150,flow:null,discharge:null,suction:null,status:'PENDING'}],summary:'',notes:'',cover:null,sections:['cover','inspection','performance','findings','appendix'],revision:1,snapshots:[],history:[]} ]});
function validate(p,photos=[]){let issues=[];if(!p.customer.trim())issues.push({view:'projects',text:'ยังไม่ได้ระบุชื่อลูกค้า'});if(!p.serial)issues.push({view:'projects',text:'ยังไม่ได้ระบุ Serial Number ของอุปกรณ์'});for(const [id,label] of questions){const a=p.answers[id];if(!a?.value)issues.push({view:'checklist',text:'ยังไม่ได้ตรวจ: '+label});else if(a.value==='N'&&!a.remark?.trim())issues.push({view:'checklist',text:'ระบุข้อบกพร่อง: '+label});}for(const t of p.tests){if(t.status==='PENDING')issues.push({view:'tests',text:`ยังไม่ได้บันทึกผลทดสอบ ${t.point}%`});if(t.status==='TESTED'&&[t.flow,t.discharge,t.suction].some(v=>v===null||v===''||!Number.isFinite(Number(v))))issues.push({view:'tests',text:`ข้อมูลผลทดสอบ ${t.point}% ไม่ครบ`});if(t.status==='NOT_TESTED'&&!t.reason?.trim())issues.push({view:'tests',text:`ระบุเหตุผลที่ไม่ได้ทดสอบ ${t.point}%`});}if(!photos.filter(a=>!a.source).length)issues.push({view:'photos',text:'ยังไม่มีรูปหลักฐานในโครงการ'});if(!p.summary.trim())issues.push({view:'builder',text:'ยังไม่ได้เขียนสรุปผลตรวจ'});return issues;}
function narrative(p){let done=Object.values(p.answers).filter(a=>a.value).length,defects=questions.filter(([id])=>p.answers[id]?.value==='N');let out=`บันทึกผลการตรวจสอบระบบ Fire Pump ณ ${p.customer} ${p.site} วันที่ ${p.date} โดยบันทึกแบบตรวจแล้ว ${done} จาก ${questions.length} รายการ`;
if(defects.length)out+=' พบรายการผิดปกติ '+defects.map(([id,label])=>label+' ('+(p.answers[id].remark||'รอรายละเอียด')+')').join(' และ');for(const t of p.tests){if(t.status==='NOT_TESTED')out+=` ไม่ได้ทดสอบที่ ${t.point}% เนื่องจาก ${t.reason||'รอระบุเหตุผล'}`;else if(t.status==='TESTED')out+=` จุดทดสอบ ${t.point}% มีอัตราการไหล ${t.flow??'ยังไม่ระบุ'} GPM แรงดันด้านส่ง ${t.discharge??'ยังไม่ระบุ'} PSI และด้านดูด ${t.suction??'ยังไม่ระบุ'} PSI`;}
return out+' ผลการประเมินทางวิศวกรรมอยู่ระหว่างรอผู้มีอำนาจตรวจทาน ยังไม่มีการรับรองผลมาตรฐาน';}
function cloneProject(p){return {...p,id:'p'+Date.now(),code:'PM.FP.NEW-'+Date.now().toString().slice(-4),date:new Date().toISOString().slice(0,10),status:'DRAFT',answers:{},tests:p.tests.map(t=>({point:t.point,flow:null,discharge:null,suction:null,status:'PENDING'})),summary:'',notes:'',cover:null,revision:1,snapshots:[],history:[]};}
const api={questions,seed,validate,narrative,cloneProject};if(typeof module!=='undefined')module.exports=api;else root.ReportModel=api;
})(typeof window==='undefined'?globalThis:window);
